<template>
  <div class="setting flex flex-col">
    <div class="flex mb-0">
      <label class="ml-0 mb-0 max-w-full mr-1">{{ label }}</label>
      <div class="inher">
        <Switch v-model="value" @toggle="change" />
        <!-- <Toggle class="max-w-full" v-model="value" @change="change" :labelledby="name" :describedby="name" /> -->
      </div>
    </div>
    <small>{{ description }}</small>
  </div>
</template>

<script>
import Switch from "../../../../components/Switch.vue";
export default {
  name: "ToggleOption",
  props: ["id", "label", "name", "description"],
  components: {
    Switch,
  },
  data() {
    return {
      value: false,
    };
  },
  methods: {
    change() {
      // eslint-disable-next-line no-undef
      mp.trigger("MenuChangeSettings", this.id, this.value);
    },
  },
};
</script>

<style scoped lang="scss">
.setting {
  color: $white-text;

  small {
    color: darken($white-text, 40%);
  }
}
</style>
