<template>
  <span></span>
</template>

<script>
import { useUserStore } from "../stores/user";
import { useCrosshairStore } from "../stores/crosshair";

export default {
  name: "States",
  setup() {
    return {
      crosshair: useCrosshairStore(),
      user: useUserStore(),
    };
  },
  methods: {
    setUser(keys, value) {
      if (keys.length > 1) return (this.user[keys[0]][keys[1]] = value);
      this.user[keys[0]] = value;
    },
    setCrosshair(key, value) {
      this.crosshair[key] = value;
    },
  },
};
</script>

