<template>
  <h1 style="position: absolute"></h1>
</template>

<script>
export default {
  name: "Tutorial",
  mounted() {
    //this.startTutorial();
  },
  data() {
    return {
      bigLogo: require("../assets/images/logo-big.png"),
      //type 1 - text only || type 2 - enabel/disable buttons || type 3 - select
      pages: [
        {
          type: 1,
          title: "Text Only",
          text: "Description here",
        },
        {
          type: 2,
          title: "Enable/disable Option",
          text: "Description aaaaa",
        },
        {
          type: 3,
          title: "Language",
          text: "Select your language",
          options: ["English", "French", "German", "Spanish", "Italian"],
        },
      ],
      results: [],
    };
  },
  methods: {
    runPage(page) {
      let footer = `${this.pages.indexOf(page) + 1}/${this.pages.length}`;
      let confirmBtnColor = "#4E98F9";
      let denyBtnColor = "#ff5a57";

      const next = (value = null) => {
        this.results.push(value);
        let nextIndex = this.pages.indexOf(page) + 1;
        if (nextIndex < this.pages.length) {
          this.runPage(this.pages[nextIndex]);
        } else {
          global.Modal.fire({
            imageUrl: this.bigLogo,
            imageHeight: "80px",
            imageAlt: "RnC Logo",
            text: "Tutorial Completed",
            confirmButtonColor: "#22c55e",
            confirmButtonText: "Start Playing",
            // showDenyButton: true,
            // denyButtonColor: "#ff5a57",
            // denyButtonText: "Skip",
            focusConfirm: true,
          });
          // eslint-disable-next-line no-undef
          mp.trigger("OnFinishTutorial", this.results);
          console.log("finished ", this.results);
        }
      };

      switch (page.type) {
        case 1:
          global.Modal.fire({
            allowOutsideClick: false,
            title: page.title,
            text: page.text,
            confirmButtonColor: confirmBtnColor,
            confirmButtonText: "Continue",
            footer: footer,
          }).then(() => {
            next();
          });
          break;
        case 2:
          global.Modal.fire({
            allowOutsideClick: false,
            title: page.title,
            text: page.text,
            confirmButtonColor: confirmBtnColor,
            confirmButtonText: "Enable",
            showDenyButton: true,
            denyButtonColor: denyBtnColor,
            denyButtonText: "Disable",
            footer: footer,
          }).then((r) => {
            next(r.isConfirmed);
          });
          break;
        case 3:
          global.Modal.fire({
            allowOutsideClick: false,
            title: page.title,
            input: "select",
            inputOptions: page.options,
            inputPlaceholder: page.placeholder,
            confirmButtonColor: confirmBtnColor,
            confirmButtonText: "Select",
            footer: footer,
          }).then((r) => {
            next(page.options[r.value]);
          });
          break;
      }
    },
    start(pages) {
      this.pages = pages;
      const startModal = {
        allowOutsideClick: false,
        imageUrl: this.bigLogo,
        imageHeight: "80px",
        imageAlt: "RnC Logo",
        confirmButtonColor: "#4E98F9",
        confirmButtonText: "Start Tutorial",
        // showDenyButton: true,
        // denyButtonColor: "#ff5a57",
        // denyButtonText: "Skip",
        focusConfirm: true,
      };

      global.Modal.fire(startModal).then((result) => {
        if (result.isConfirmed) {
          this.runPage(this.pages[0]);
        } else if (result.isDenied) {
          //send to srw that user skiped tutorial
        }
      });
    },
  },
};
</script>
