<template>
  <button
    v-if="debug"
    style="position: absolute; bottom: 0; right: 250px"
    @click="
      add(
        makeid(getRndInteger(4, 12)),
        `#${Math.floor(Math.random() * 16777215).toString(16)}`,
        'AK47',
        makeid(getRndInteger(4, 12)),
        `#${Math.floor(Math.random() * 16777215).toString(16)}`
      )
    "
  >
    addKill
  </button>
  <div class="feed" v-if="enabled">
    <transition-group name="slide-in-blurred-right" appear>
      <div v-for="kill in killFeed" :key="kill.PushTime" class="feed-item">
        <span
          v-if="kill.Killer"
          class="feed-person"
          :style="{
            background: kill.KillerColor,
            color: lightOrDark(kill.KillerColor),
          }"
          >{{ kill.Killer }}</span
        ><span v-if="kill.Weapon" class="feed-weapon">{{ kill.Weapon }}</span
        ><span
          v-if="kill.Victim"
          class="feed-person"
          :style="{
            background: kill.VictimColor,
            color: lightOrDark(kill.VictimColor),
          }"
          >{{ kill.Victim }}</span
        >
      </div>
    </transition-group>
  </div>
</template>

<script>
export default {
  name: "KillFeed",
  data() {
    return {
      enabled: false,
      killFeed: [],
      debug: false,
    };
  },
  methods: {
    getRndInteger(min, max) {
      return Math.floor(Math.random() * (max - min)) + min;
    },
    add(
      killer = null,
      killerColor = null,
      weapon = null,
      victim = null,
      victimColor = null
    ) {
      if (this.killFeed.length === 7) this.killFeed.pop();
      this.killFeed.unshift({
        Killer: killer,
        KillerColor: killerColor,
        Weapon: weapon,
        Victim: victim,
        VictimColor: victimColor,
        PushTime: new Date().getTime(),
      });
    },
    lightOrDark(color) {
      let r, g, b, hsp;
      // Check the format of the color, HEX or RGB?
      if (color.match(/^rgb/)) {
        // If HEX --> store the red, green, blue values in separate variables
        color = color.match(
          /^rgba?\((\d+),\s*(\d+),\s*(\d+)(?:,\s*(\d+(?:\.\d+)?))?\)$/
        );

        r = color[1];
        g = color[2];
        b = color[3];
      } else {
        // If RGB --> Convert it to HEX: http://gist.github.com/983661
        color = +(
          "0x" + color.slice(1).replace(color.length < 5 && /./g, "$&$&")
        );

        r = color >> 16;
        g = (color >> 8) & 255;
        b = color & 255;
      }

      // HSP (Highly Sensitive Poo) equation from http://alienryderflex.com/hsp.html
      hsp = Math.sqrt(0.299 * (r * r) + 0.587 * (g * g) + 0.114 * (b * b));

      // Using the HSP value, determine whether the color is light or dark
      if (hsp > 127.5) {
        return "rgba(43,43,43,0.8)";
      } else {
        return "rgba(255, 255, 255, 0.8)";
      }
    },
    makeid(length) {
      var result = "";
      var characters =
        "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789";
      var charactersLength = characters.length;
      for (var i = 0; i < length; i++) {
        result += characters.charAt(
          Math.floor(Math.random() * charactersLength)
        );
      }
      return result;
    },
  },
};
</script>

<style scoped lang="scss">
.slide-in-blurred-right-enter-active {
  //animation: slide-in-blurred-right 0.2s cubic-bezier(0.230, 1.000, 0.320, 1.000) both;
  animation: scale-in-center 0.1s cubic-bezier(0.25, 0.46, 0.45, 0.94) both;
}

@keyframes scale-in-center {
  0% {
    -webkit-transform: scale(0);
    transform: scale(0);
    opacity: 1;
  }
  100% {
    -webkit-transform: scale(1);
    transform: scale(1);
    opacity: 1;
  }
}

/*.slide-in-blurred-right-leave-active {
  animation: slide-out-blurred-bottom 0.2s cubic-bezier(0.755, 0.050, 0.855, 0.060) both;
}*/
.feed {
  justify-content: right;
  justify-items: right;
  width: 100%;
  font-family: "Nunito", sans-serif;
  font-weight: 500;
  font-size: 15px;
  display: grid;
  align-items: center;
  //max-height: 255px;
  max-height: 225px;

  .feed-item {
    margin: 5px 0px;
    background: rgba($background, 0.4);
    display: flex;
    justify-content: center;
    align-items: center;
    border-radius: 15px;
    min-height: 0;
    height: 35px;

    .feed-person {
      padding: 10px 20px;
      border-radius: 15px;
      background: yellow;
      height: 100%;
      display: flex;
      justify-content: center;
      align-items: center;
    }

    .feed-weapon {
      padding: 10px 20px;
      color: rgba(255, 255, 255, 0.7);
    }
  }
}

@keyframes slide-in-blurred-right {
  0% {
    -webkit-transform: translateX(1000px) scaleX(2.5) scaleY(0.2);
    transform: translateX(1000px) scaleX(2.5) scaleY(0.2);
    -webkit-transform-origin: 0% 50%;
    transform-origin: 0% 50%;
    -webkit-filter: blur(40px);
    filter: blur(40px);
    opacity: 0;
  }
  100% {
    -webkit-transform: translateX(0) scaleY(1) scaleX(1);
    transform: translateX(0) scaleY(1) scaleX(1);
    -webkit-transform-origin: 50% 50%;
    transform-origin: 50% 50%;
    -webkit-filter: blur(0);
    filter: blur(0);
    opacity: 1;
  }
}

@keyframes slide-out-blurred-bottom {
  0% {
    -webkit-transform: translateY(0) scaleY(1) scaleX(1);
    transform: translateY(0) scaleY(1) scaleX(1);
    -webkit-transform-origin: 50% 50%;
    transform-origin: 50% 50%;
    -webkit-filter: blur(0);
    filter: blur(0);
    opacity: 1;
  }
  100% {
    -webkit-transform: translateY(1000px) scaleY(2) scaleX(0.2);
    transform: translateY(1000px) scaleY(2) scaleX(0.2);
    -webkit-transform-origin: 50% 100%;
    transform-origin: 50% 100%;
    -webkit-filter: blur(40px);
    filter: blur(40px);
    opacity: 0;
  }
}
</style>
