<template>
  <div class="layers">
    <draggable
      :list="crosshair.getSelectedLayers"
      item-key="uuid"
      v-bind="{ animation: 200 }"
      handle=".handle"
      :force-fallback="true"
    >
      <template #item="{ index }">
        <div class="layer">
          <CrosshairLayer :index="index" />
        </div>
      </template>
    </draggable>
    <div
      v-if="crosshair.getSelectedLayers.length < 10"
      class="w-full flex items-center justify-center p-2 gap-3"
    >
      <Button @click="crosshair.addLayer(newType.value)">New Layer</Button>
      <v-select
        v-model="newType"
        class="w-52"
        :options="[
          { label: 'Cross', value: 0 },
          { label: 'Circle', value: 1 },
        ]"
        :clearable="false"
        :searchable="false"
      ></v-select>
    </div>
  </div>
</template>

<script>
/* eslint-disable */
import CrosshairLayer from "./CrosshairLayer.vue";
import draggable from "vuedraggable";
import Button from "../../../../../components/Button.vue";
import { useCrosshairStore } from "../../../../../stores/crosshair";

export default {
  name: "CrosshairLayers",
  components: { CrosshairLayer, draggable, Button },
  setup() {
    return { crosshair: useCrosshairStore() };
  },
  data() {
    return {
      drag: false,
      newType: { label: "Cross", value: 0 },
    };
  },
};
</script>

<style lang="scss" scoped>
.layers {
  max-height: 660px;
  height: 660px;
  overflow: hidden;
  border-radius: $radius-sm;
  overflow-y: auto;
  padding-right: 5px;
  margin: 5px 0;
}
</style>
