<template>
  <div class="SettingsList grid gap-5 max-h-full p-5 overflow-y-auto">
    <template v-for="option in options">
      <ToggleOption
        v-if="option.type === 1"
        :key="option.name"
        :id="option.id"
        :label="option.label"
        :name="option.name"
        :description="option.description"
        :ref="option.name"
      />

      <RadioOption
        v-if="option.type === 2"
        :key="option.name"
        :id="option.id"
        :label="option.label"
        :name="option.name"
        :description="option.description"
        :options="option.options"
        :ref="option.name"
      />

      <BindOption
        v-if="option.type === 3"
        :key="option.name"
        :id="option.id"
        :label="option.label"
        :name="option.name"
        :description="option.description"
        :ref="option.name"
      />

      <SelectOption
        v-if="option.type === 4"
        :key="option.name"
        :id="option.id"
        :label="option.label"
        :name="option.name"
        :description="option.description"
        :options="option.options"
        :ref="option.name"
        :preSelect="option.preSelect ? option.preSelect : null"
        :devMode="devMode"
      />
    </template>
  </div>
</template>

<script>
/*
Types: 1 = toggle | 2 = radio | 3 = bind
*/
/* eslint-disable vue/no-unused-components */

import ToggleOption from "./ToggleOption";
import RadioOption from "./RadioOption";
import BindOption from "./BindOption";
import SelectOption from "./SelectOption";

export default {
  name: "Settings",
  props: ["options", "devMode"],
  components: {
    ToggleOption,
    RadioOption,
    BindOption,
    SelectOption,
  },
};
</script>

<style lang="scss" scoped>
.SettingsList {
  max-height: 720px;
  border-radius: $radius-md;
}
</style>
